package io.jafar.arch;

import com.tngtech.archunit.lang.ArchRule;
import com.tngtech.archunit.library.freeze.FreezingArchRule;
import org.junit.jupiter.api.Test;

/**
 * The boundary rules (a)–(e) as freeze rules (AC-2.1/AC-2.2): each rule is checked against the real
 * module classes with the committed violation store ({@code
 * arch-tests/src/test/resources/archunit_store}), so the suite is green on the branch base and
 * fails only on NEW violations — existing reach-ins are grandfathered, never fixed here.
 *
 * <p>The store is generated by {@code ./gradlew :arch-tests:test -ParchFreeze} and can only shrink
 * (see {@code archunit.properties}: no run can add violations). ArchRuleFireTest proves both that
 * each rule fires and that the CI configuration cannot grow the store.
 */
class ArchitectureRulesTest {

  // one import per JVM: loading is the expensive part and every rule checks the same classes
  private static final ModuleClasses MODULES = ModuleClasses.load();

  @Test
  void ruleA_outsideParserPlaneMustNotReachIntoParserImpl() {
    frozen(ArchitectureRules.ruleA(MODULES));
  }

  @Test
  void ruleB_outsideHdumpParserMustNotReachIntoHdumpImpl() {
    frozen(ArchitectureRules.ruleB(MODULES));
  }

  @Test
  void ruleC_apiPackagesMustNotDependOnImplementationPackages() {
    for (ArchRule rule : ArchitectureRules.ruleC(MODULES)) {
      frozen(rule);
    }
  }

  @Test
  void ruleD_parserModulesAndShellCoreMustNotDependOnConsumers() {
    frozen(ArchitectureRules.ruleD(MODULES));
  }

  @Test
  void ruleE_parserImplementationPackagesMustHaveNoMutableStaticFields() {
    frozen(ArchitectureRules.ruleE(MODULES));
  }

  private static void frozen(ArchRule rule) {
    FreezingArchRule.freeze(rule).check(MODULES.classes());
  }
}
